#include <xrudp.h>
#include <xrt/crc32.h>
#include <stdio.h>
#include <string.h>
#define CHECK(e) do { if(!(e)) { fprintf(stderr,"%s:%d: %s\n",__FILE__,__LINE__,#e);return 1; } } while(0)
static const unsigned char transaction[12]={1,0x23,0x45,0x67,0x89,0xab,0xcd,0xef,0x10,0x32,0x54,0x76};
/* Independent Python stdlib struct/ipaddress/zlib vectors, not a roundtrip
 * generated by the C encoder. Source inputs and receipt retained in out/. */
static const unsigned char golden4[]={0x01,0x01,0x00,0x14,0x21,0x12,0xa4,0x42,0x01,0x23,0x45,0x67,0x89,0xab,0xcd,0xef,0x10,0x32,0x54,0x76,0x00,0x20,0x00,0x08,0x00,0x01,0xa1,0x47,0xe1,0x12,0xa6,0x43,0x80,0x28,0x00,0x04,0x7c,0x30,0x65,0xf9};
static const unsigned char golden6[]={0x01,0x01,0x00,0x20,0x21,0x12,0xa4,0x42,0x01,0x23,0x45,0x67,0x89,0xab,0xcd,0xef,0x10,0x32,0x54,0x76,0x00,0x20,0x00,0x14,0x00,0x02,0xa1,0x47,0x01,0x13,0xa9,0xfa,0x13,0x17,0x13,0x1f,0x89,0xba,0xef,0xdc,0x54,0x67,0x32,0x01,0x80,0x28,0x00,0x04,0xba,0xd7,0x1e,0x9d};
static xrudpaddress mapped4={4,32853,0,{192,0,2,1}},mapped6={6,32853,0,{0x20,1,0xd,0xb8,0x12,0x34,0x56,0x78,0,0x11,0x22,0x33,0x44,0x55,0x66,0x77}};
static void put16(unsigned char* p,uint16_t n) {p[0]=(unsigned char)(n>>8);p[1]=(unsigned char)n;}
static bool address_equal(const xrudpaddress* a,const xrudpaddress* b) {return a->Family==b->Family && a->Port==b->Port && a->Zone==b->Zone && !memcmp(a->Address,b->Address,16);}
static int vectors(void)
{
	unsigned char bytes[600],saved[600];size_t n;xrudpstunmessage m,before;
	for(uint32_t family=0;family<2;++family) {
		const unsigned char* golden=family?golden6:golden4;size_t length=family?sizeof(golden6):sizeof(golden4);xrudpaddress* address=family?&mapped6:&mapped4;
		CHECK(xrtRudpStunDecode(golden,length,&m)==XRUDP_OK && m.Type==XRUDP_STUN_BINDING_SUCCESS && m.HasMapped && m.Fingerprint && !m.Integrity && !m.UnknownCount && address_equal(&m.Mapped,address) && !memcmp(m.Transaction,transaction,12));
		CHECK(xrtRudpStunResponse(transaction,address,true,bytes,sizeof(bytes),&n)==XRUDP_OK && n==length && !memcmp(bytes,golden,n));
		for(size_t cut=0;cut<length;++cut) {memset(&m,0xa5,sizeof(m));before=m;CHECK(xrtRudpStunDecode(golden,cut,&m)!=XRUDP_OK && !memcmp(&m,&before,sizeof(m)));}
		for(size_t bit=0;bit<length*8;++bit) {
			memcpy(bytes,golden,length);bytes[bit/8]^=(unsigned char)(1u<<(bit%8));
			if(xrtRudpStunDecode(bytes,length,&m)==XRUDP_OK)CHECK(!m.Fingerprint); /* A changed optional type can remove, not forge, CRC presence. */
		}
		for(size_t cap=0;cap<length;++cap) {memset(bytes,0xa5,sizeof(bytes));memcpy(saved,bytes,sizeof(bytes));CHECK(xrtRudpStunResponse(transaction,address,true,bytes,cap,&n)==XRUDP_LIMIT && !n && !memcmp(bytes,saved,sizeof(bytes)));}
		CHECK(xrtRudpStunResponse(transaction,address,false,bytes,sizeof(bytes),&n)==XRUDP_OK && n==length-8 && xrtRudpStunDecode(bytes,n,&m)==XRUDP_OK && !m.Fingerprint);
	}
	CHECK(xrtRudpStunRequest(transaction,false,bytes,sizeof(bytes),&n)==XRUDP_OK && n==20 && xrtRudpStunDecode(bytes,n,&m)==XRUDP_OK && m.Type==XRUDP_STUN_BINDING_REQUEST);
	CHECK(xrtRudpStunRequest(transaction,true,bytes,sizeof(bytes),&n)==XRUDP_OK && n==28 && xrtRudpStunDecode(bytes,n,&m)==XRUDP_OK && m.Fingerprint);
	memcpy(bytes,transaction,12);CHECK(xrtRudpStunRequest(bytes,true,bytes,sizeof(bytes),&n)==XRUDP_OK && !memcmp(bytes+8,transaction,12));
	uint16_t unknown[]={0x222,0x223};CHECK(xrtRudpStunError(transaction,420,unknown,2,true,bytes,sizeof(bytes),&n)==XRUDP_OK && xrtRudpStunDecode(bytes,n,&m)==XRUDP_OK && m.ErrorCode==420 && m.Fingerprint);
	CHECK(xrtRudpStunError(transaction,300,NULL,0,false,bytes,sizeof(bytes),&n)==XRUDP_OK && xrtRudpStunDecode(bytes,n,&m)==XRUDP_OK && m.ErrorCode==300);
	CHECK(xrtRudpStunError(transaction,420,NULL,0,false,bytes,sizeof(bytes),&n)==XRUDP_ARGUMENT && !n);
	CHECK(xrtRudpStunError(transaction,700,NULL,0,false,bytes,sizeof(bytes),&n)==XRUDP_ARGUMENT && !n);
	return 0;
}
static int attributes(void)
{
	unsigned char p[600],saved[600];size_t n;xrudpstunmessage m,before;
	CHECK(xrtRudpStunResponse(transaction,&mapped4,false,p,sizeof(p),&n)==XRUDP_OK && n==32);
	/* Padding may be arbitrary; unknown optional is ignored, required collected. */
	put16(p+n,0x8123);put16(p+n+2,1);p[n+4]=7;p[n+5]=p[n+6]=p[n+7]=0xa5;n+=8;put16(p+2,(uint16_t)(n-20));
	CHECK(xrtRudpStunDecode(p,n,&m)==XRUDP_OK && m.HasMapped && !m.UnknownCount);
	put16(p+n,0x123);put16(p+n+2,0);n+=4;put16(p+2,(uint16_t)(n-20));CHECK(xrtRudpStunDecode(p,n,&m)==XRUDP_OK && m.UnknownCount==1 && m.Unknown[0]==0x123);
	memcpy(p+n,p+n-4,4);n+=4;put16(p+2,(uint16_t)(n-20));CHECK(xrtRudpStunDecode(p,n,&m)==XRUDP_OK && m.UnknownCount==1);
	/* First occurrence wins; later malformed values do not replace it. */
	put16(p+n,0x20);put16(p+n+2,1);memset(p+n+4,0xff,4);n+=8;put16(p+2,(uint16_t)(n-20));CHECK(xrtRudpStunDecode(p,n,&m)==XRUDP_OK && address_equal(&m.Mapped,&mapped4));
	/* Integrity isn't verified here, and attributes after it do not become hints. */
	CHECK(xrtRudpStunRequest(transaction,false,p,sizeof(p),&n)==XRUDP_OK);put16(p+n,8);put16(p+n+2,20);memset(p+n+4,0,20);n+=24;
	memcpy(p+n,golden4+20,12);n+=12;put16(p+2,(uint16_t)(n-20));CHECK(xrtRudpStunDecode(p,n,&m)==XRUDP_OK && m.Integrity && !m.HasMapped);
	CHECK(xrtRudpStunRequest(transaction,false,p,sizeof(p),&n)==XRUDP_OK);
	for(uint16_t i=0;i<17;++i) {put16(p+n,(uint16_t)(0x100+i));put16(p+n+2,0);n+=4;}
	put16(p+2,(uint16_t)(n-20));CHECK(xrtRudpStunDecode(p,n,&m)==XRUDP_LIMIT);
	CHECK(xrtRudpStunRequest(transaction,false,p,sizeof(p),&n)==XRUDP_OK);
	for(uint16_t i=0;i<65;++i) {put16(p+n,0x9000);put16(p+n+2,0);n+=4;}
	put16(p+2,(uint16_t)(n-20));CHECK(xrtRudpStunDecode(p,n,&m)==XRUDP_LIMIT);
	memcpy(p,golden4,sizeof(golden4));memset(&m,0xa5,sizeof(m));before=m;p[39]^=1;CHECK(xrtRudpStunDecode(p,sizeof(golden4),&m)==XRUDP_MALFORMED && !memcmp(&m,&before,sizeof(m)));
	memset(p,0xa5,sizeof(p));memcpy(saved,p,sizeof(p));xrudpaddress invalid=mapped4;invalid.Zone=1;CHECK(xrtRudpStunResponse(transaction,&invalid,true,p,sizeof(p),&n)==XRUDP_ARGUMENT && !n && !memcmp(p,saved,sizeof(p)));
	return 0;
}
static int mutations(void)
{
	uint32_t seed=0x723f1901;unsigned char p[600];xrudpstunmessage m,before;
	for(uint32_t step=0;step<40000;++step) {
		seed=seed*1664525u+1013904223u;size_t n=seed%514;
		for(size_t i=0;i<n;++i) {seed=seed*1664525u+1013904223u;p[i]=(unsigned char)(seed>>24);}
		if(step%2 && n>=sizeof(golden6)) {memcpy(p,golden6,sizeof(golden6));seed=seed*1664525u+1013904223u;p[seed%sizeof(golden6)]^=(unsigned char)(1u<<(step%8));}
		memset(&m,0xa5,sizeof(m));before=m;xrudpresult r=xrtRudpStunDecode(p,n,&m);if(r!=XRUDP_OK)CHECK(!memcmp(&m,&before,sizeof(m)));
	}
	return 0;
}
int main(void)
{
	CHECK(vectors()==0 && attributes()==0 && mutations()==0);
	puts("xrudp STUN: independent IPv4/IPv6 vectors, fingerprint, bounded attributes, atomic rejection and40000 mutations passed");return 0;
}
